import{_ as t,o as r,c as n,a2 as a}from"./chunks/framework.vLhlLNVn.js";const i="/assets/adapter-startet-nicht.94Ga1nmg.svg",m=JSON.parse('{"title":"Verbindung und Adapterstart","description":"","frontmatter":{"order":1,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/04.fehlerbehebung/01.verbindung-und-start.md"},"headers":[],"relativePath":"de/adapter/wled/fehlerbehebung/verbindung-und-start.md","filePath":"de/adapter/wled/fehlerbehebung/verbindung-und-start.md","lastUpdated":null}'),d={name:"de/adapter/wled/fehlerbehebung/verbindung-und-start.md"};function s(o,e,l,u,h,c){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="verbindung-und-adapterstart" tabindex="-1">Verbindung und Adapterstart <a class="header-anchor" href="#verbindung-und-adapterstart" aria-label="Permalink to &quot;Verbindung und Adapterstart&quot;">​</a></h1><p><a id="adapter-not-start-stop-responding"></a></p><h2 id="warum-startet-der-adapter-nach-einem-update-nicht-oder-reagiert-nicht-mehr" tabindex="-1">Warum startet der Adapter nach einem Update nicht oder reagiert nicht mehr? <a class="header-anchor" href="#warum-startet-der-adapter-nach-einem-update-nicht-oder-reagiert-nicht-mehr" aria-label="Permalink to &quot;Warum startet der Adapter nach einem Update nicht oder reagiert nicht mehr?&quot;">​</a></h2><p><strong>Kurz:</strong> Schau zuerst ins Log der Instanz <code>wled.&lt;Instanz&gt;</code>. Die bekannten Ursachen sind: Voraussetzungen wie die Node.js-Version nicht erfüllt, ein unvollständig installiertes Update, Fehler älterer Adapterversionen und in v0.9.2 ein Polling-Intervall von 0 oder Geräte, die nach dem Start hinzukamen. Die Tabelle unten ordnet die Log-Zeilen zu.</p><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne im Admin den Reiter „Log“ und suche die Zeilen der Instanz <code>wled.&lt;Instanz&gt;</code> und die Zeilen <code>host.&lt;Host&gt;</code> direkt nach dem Start der Instanz. Startet der Adapter gar nicht, steht der Fehler oft beim Host mit <code>Caught by controller</code>.</li><li>Vergleiche die Zeilen mit der Tabelle unten und folge der Lösung.</li><li>Starte die Instanz danach neu.</li><li>Bleibt der Fehler, stelle die Log-Stufe der Instanz auf „debug“, starte sie neu und hänge den Log-Auszug an ein <a href="https://github.com/DrozmotiX/ioBroker.wled/issues" target="_blank" rel="noreferrer">GitHub-Issue</a>. Ersetze vorher IP- und MAC-Adressen.</li></ol><h3 id="bekannte-ursachen-und-log-zeilen" tabindex="-1">Bekannte Ursachen und Log-Zeilen <a class="header-anchor" href="#bekannte-ursachen-und-log-zeilen" aria-label="Permalink to &quot;Bekannte Ursachen und Log-Zeilen&quot;">​</a></h3><p><img src="'+i+'" alt="Entscheidungsbaum: Prüfe der Reihe nach, ob die Installation eine zu alte Node.js-Version meldet, ob „Cannot find module“ im Log steht, ob Meldungen alter Versionen erscheinen, ob viele Zeilen „Unable to initialise“ kommen, ob die Last ohne Fehlermeldung hoch ist oder ob ein Gerät nach einem Ausfall nicht mehr reagiert. Passt nichts, hängst du ein Debug-Log an ein GitHub-Issue."></p><table tabindex="0"><thead><tr><th>Log-Zeile (Auszug)</th><th>Ursache</th><th>Lösung</th></tr></thead><tbody><tr><td>Kein Start nach dem Update, die Installation meldet eine zu alte Node.js-Version</td><td>Der Adapter braucht in v0.9.2 Node.js 20 oder neuer, js-controller 6.0.11 oder neuer und Admin 7.6.17 oder neuer.</td><td>Aktualisiere Node.js, js-controller oder Admin.</td></tr><tr><td><code>Caught by controller[0]: Error: Cannot find module &#39;axios&#39;</code></td><td>Das Update wurde nicht vollständig installiert, eine Bibliothek des Adapters fehlt.</td><td>Installiere den Adapter im Reiter „Adapter“ erneut oder eine neuere Version.</td></tr><tr><td><code>[handleStates] TypeError: Cannot read property &#39;initialized&#39; of undefined</code></td><td>Fehler in Versionen vor v0.6.7, behoben in v0.6.7.</td><td>Aktualisiere den Adapter.</td></tr><tr><td><code>Caught by controller[0]: State attribute definition missing for …</code>, danach beendet sich die Instanz</td><td>Fehler in v0.5.x. Seit v0.7.1 ist die Meldung nur noch eine Debug-Meldung ohne Folgen.</td><td>Aktualisiere den Adapter.</td></tr><tr><td>Viele Zeilen <code>Unable to initialise 192.168.x.y will retry in scheduled interval !</code> und <code>Device 192.168.x.y unavailable (attempt n/5), will retry in … seconds</code></td><td>Ein Gerät ist ausgeschaltet oder nicht erreichbar. Der Adapter läuft, das Log füllt sich aber bei jedem Versuch.</td><td>Schalte das Gerät ein oder lösche es, wenn du es nicht mehr nutzt.</td></tr><tr><td>Nach jedem Fehler eine zweite Zeile <code>Sentry disabled, error caught : …</code></td><td>Der Adapter meldet jeden Fehler doppelt. Es ist derselbe Fehler.</td><td>Werte nur die erste Zeile aus.</td></tr><tr><td>Keine Fehlermeldung, aber der Adapter reagiert nicht mehr und die Last ist hoch</td><td>„Intervall in Sekunden“ steht auf 0. Die Abfragen laufen dann ohne Pause.</td><td>Stelle das Intervall auf mindestens 1 Sekunde, voreingestellt sind 30 Sekunden.</td></tr><tr><td>Keine Fehlermeldung, aber ein Gerät reagiert nach einem Ausfall nicht mehr</td><td>Das Gerät kam nach dem Adapterstart dazu, über „Neue Geräte suchen“, per IP oder weil die Bonjour-Suche es erst später fand. Für solche Geräte startet in v0.9.2 keine Überwachung, sie verbinden sich nach einem Ausfall nicht neu.</td><td>Starte die Instanz neu.</td></tr></tbody></table><p>Die beiden Zeilen zu <code>State attribute definition missing</code> und <code>Cannot read property &#39;initialized&#39;</code> stammen aus alten Versionen. Siehst du sie heute noch, läuft bei dir eine alte Adapterversion.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Die Einstellung „Maximale Wiederholungsversuche“ gilt für alle Geräte der Instanz gemeinsam. Eine Einstellung je Gerät gibt es nicht.</p></div><h3 id="ab-v0-9-3" tabindex="-1">Ab v0.9.3 <a class="header-anchor" href="#ab-v0-9-3" aria-label="Permalink to &quot;Ab v0.9.3&quot;">​</a></h3><p><strong>Ab v0.9.3:</strong> Der Adapter braucht Node.js 22 oder neuer und Admin 7.6.20 oder neuer. Prüfe das vor dem Update.</p><p><strong>Ab v0.9.3:</strong> Ein Polling-Intervall unter 1 Sekunde oder eine ungültige Zahl an Wiederholungen ersetzt der Adapter beim Start durch den Standard und warnt einmal: <code>Invalid polling interval &quot;0&quot;, using 30 seconds</code> oder <code>Invalid number of retry attempts &quot;0&quot;, using 5</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/924" target="_blank" rel="noreferrer">#924</a>). Korrigiere dann die Einstellung, damit die Warnung verschwindet.</p><p><strong>Ab v0.9.3:</strong> Ein Ausfall steht im Log als eine Warnung, zum Beispiel <code>Unable to initialise 192.168.x.y will retry in scheduled interval !</code> oder <code>Heartbeat of device 192.168.x.y failed, will try to reconnect</code>. Die weiteren Versuche stehen nur noch auf der Stufe „debug“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/903" target="_blank" rel="noreferrer">#903</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/788" target="_blank" rel="noreferrer">#788</a>).</p><p><strong>Ab v0.9.3:</strong> Jeder Fehler steht nur einmal im Log. Die Übergabe an Sentry steht nur noch auf der Stufe „debug“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/913" target="_blank" rel="noreferrer">#913</a>).</p><p><strong>Ab v0.9.3:</strong> Auch Geräte, die nach dem Start dazukommen, werden überwacht und verbinden sich nach einem Ausfall ohne Neustart neu (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/901" target="_blank" rel="noreferrer">#901</a>). <code>_info._online</code> wird <code>false</code>, wenn ein Gerät zwei Polling-Intervalle lang nicht antwortet (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/900" target="_blank" rel="noreferrer">#900</a>).</p><p><strong>Ab v0.9.3:</strong> Einen Befehl an ein Gerät, das offline ist, verwirft der Adapter mit der Warnung <code>Device &lt;MAC&gt; (192.168.x.y) is offline, command for &lt;State&gt; discarded</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>). <code>on</code> und <code>bri</code> behalten beim Offline-Gehen und beim Adapterstart ihren letzten Wert (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>).</p><p><strong>Ab v0.10.0:</strong> Die Einstellung heißt „Abfrage-Intervall“. Du findest sie in den Instanzeinstellungen im Reiter „Einstellungen“ unter „Verbindung“, daneben „Maximale Wiederholungsversuche“. Das Formular nimmt beim Intervall nur Werte ab 1 Sekunde an, bei den Wiederholungen 1 bis 20 (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><p><strong>Ab v0.10.0:</strong> Schreibst du einen Befehl an ein Gerät, das als offline gilt, versucht der Adapter sofort, es zu erreichen, statt auf die nächste Prüfung zu warten. Antwortet das Gerät, geht der Befehl raus. Erst wenn es nicht antwortet, verwirft er ihn mit der Warnung von oben (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/939" target="_blank" rel="noreferrer">#939</a>). Zwischen zwei solchen Versuchen für dasselbe Gerät liegen mindestens 5 Sekunden.</p><p><strong>Siehe auch:</strong> <a href="./befehle-wirken-nicht#script-not-ps-wled-ignores">Warum setzt mein Skript ps oder on nicht?</a> · <a href="./../erste-schritte/installation#wled-firmware-requirements-adapter-need">Welche Voraussetzungen braucht der Adapter?</a> · <a href="./../referenz/instanz-einstellungen#often-adapter-retry-offline-device">Wie oft versucht der Adapter ein Offline-Gerät erneut zu erreichen?</a> · <a href="./../referenz/log-meldungen#warning-state-attribute-definition-missing">Was bedeutet „State attribute definition missing“?</a></p><p><a id="adapter-stop-working-after-wled"></a></p><h2 id="warum-funktioniert-der-adapter-nach-einem-wled-firmware-update-nicht-mehr-oder-segmente-nur-an-einem-gerat" tabindex="-1">Warum funktioniert der Adapter nach einem WLED-Firmware-Update nicht mehr, oder Segmente nur an einem Gerät? <a class="header-anchor" href="#warum-funktioniert-der-adapter-nach-einem-wled-firmware-update-nicht-mehr-oder-segmente-nur-an-einem-gerat" aria-label="Permalink to &quot;Warum funktioniert der Adapter nach einem WLED-Firmware-Update nicht mehr, oder Segmente nur an einem Gerät?&quot;">​</a></h2><p><strong>Kurz:</strong> Ein Firmware-Update von WLED legt den Adapter in der Regel nicht lahm. Häufige Folgen sind: Das Gerät ist während des Updates eine Weile offline, neue Effekte oder Segmente fehlen in ioBroker, oder die neue Firmware liefert Felder, die der Adapter noch nicht kennt. Starte nach dem Update die Instanz neu, damit der Adapter das Gerät komplett neu einliest. Hilft das nicht, liegt es oft an der Firmware selbst.</p><h3 id="was-nach-einem-firmware-update-passieren-kann" tabindex="-1">Was nach einem Firmware-Update passieren kann <a class="header-anchor" href="#was-nach-einem-firmware-update-passieren-kann" aria-label="Permalink to &quot;Was nach einem Firmware-Update passieren kann&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Was du siehst</th><th>Ursache</th><th>Was du tust</th></tr></thead><tbody><tr><td>Das Gerät steht nach dem Update eine Weile auf offline.</td><td>WLED startet beim Update neu. Der Adapter erkennt das als Ausfall und wartet bis zur nächsten Prüfung, nach mehreren Fehlversuchen bis zu einer Stunde.</td><td>Starte die Instanz neu oder warte. Siehe <a href="#wled-shown-offline-after-restart">Warum wird WLED nach Neustart oder Update als offline angezeigt?</a></td></tr><tr><td>Neue Effekte oder Paletten fehlen in der Auswahl von <code>fx</code> und <code>pal</code>.</td><td>Der Adapter liest die Listen in v0.9.2 nur, wenn er den Datenpunkt anlegt.</td><td>Starte die Instanz neu.</td></tr><tr><td>Neue Segmente fehlen, gelöschte Segmente stehen noch im Objektbaum.</td><td>Der Adapter legt Segmente in v0.9.2 nur beim ersten Einlesen nach dem Start an und löscht keine.</td><td>Starte die Instanz neu. Lösch alte <code>seg.&lt;Segment&gt;</code>-Ordner bei Bedarf von Hand.</td></tr><tr><td>Auf Stufe „debug“ steht <code>State attribute definition missing for : &lt;Feld&gt;</code>.</td><td>Die neue Firmware liefert ein Feld, das der Adapter nicht kennt. Er legt den Datenpunkt trotzdem an, nur lesbar.</td><td>Nichts, die Meldung ist harmlos. Siehe <a href="./../referenz/log-meldungen#warning-state-attribute-definition-missing">Was bedeutet die Warnung &quot;State attribute definition missing&quot;?</a></td></tr><tr><td>Die Warnung <code>Client 192.168.x.y does not support websocket …</code></td><td>Auf dem Gerät läuft eine Firmware älter als 0.12, etwa nach einem Downgrade. Der Adapter fragt es nur noch per HTTP ab.</td><td>Aktualisiere die Firmware auf 0.12 oder neuer.</td></tr><tr><td>Der Adapter steuert das Gerät noch, liest aber keine Werte mehr.</td><td>Eine alte Adapterversion kennt den Aufbau der Daten einer neuen WLED-Version nicht. So war es zum Beispiel beim Wechsel auf WLED 0.11.</td><td>Aktualisiere den Adapter.</td></tr><tr><td>Segmente lassen sich nur an einem Gerät steuern, oder die Steuerung fällt nach dem Update ganz aus.</td><td>Oft ein Fehler einer Vorab- oder Beta-Firmware von WLED.</td><td>Installiere die aktuelle stabile WLED-Version. Hilft das nicht, setz das Gerät in WLED zurück und richte es neu ein.</td></tr></tbody></table><h3 id="so-prufst-du-der-reihe-nach" tabindex="-1">So prüfst du der Reihe nach <a class="header-anchor" href="#so-prufst-du-der-reihe-nach" aria-label="Permalink to &quot;So prüfst du der Reihe nach&quot;">​</a></h3><ol><li>Öffne die WLED-Oberfläche unter <code>http://192.168.x.y</code>. Lässt sich das Gerät dort steuern, läuft die Firmware.</li><li>Schau in ioBroker auf <code>wled.&lt;Instanz&gt;.&lt;MAC&gt;._info.ver</code>. Dort muss die neue Firmware-Version stehen. Steht dort noch die alte, hat der Adapter das Gerät seit dem Update nicht neu eingelesen.</li><li>Starte die Instanz <code>wled.&lt;Instanz&gt;</code> neu. Der Adapter liest dabei alle Geräte neu ein und legt fehlende Datenpunkte an.</li><li>Prüf <code>_info._online</code> und steuere das Gerät einmal von Hand aus dem Objektbaum, zum Beispiel über <code>on</code>.</li><li>Klappt es dann noch nicht, stell die Log-Stufe der Instanz auf „debug“, starte sie neu und hänge den Log-Auszug mit der WLED-Version an ein <a href="https://github.com/DrozmotiX/ioBroker.wled/issues" target="_blank" rel="noreferrer">GitHub-Issue</a>. Ersetze vorher IP- und MAC-Adressen.</li></ol><p><strong>Ab v0.9.3:</strong> Die Listen für <code>fx</code> und <code>pal</code> liest der Adapter bei jedem Wiederverbinden neu. Neue Effekte erscheinen nach einem Firmware-Update ohne Neustart (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/912" target="_blank" rel="noreferrer">#912</a>). Segmente, die du in WLED anlegst oder löschst, gleicht der Adapter ohne Neustart ab (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/909" target="_blank" rel="noreferrer">#909</a>).</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/installation#wled-firmware-requirements-adapter-need">Welche WLED-Firmware braucht der Adapter?</a> · <a href="./segmente-und-synchronisation#segment-states-not-appear-remain">Warum erscheinen Segment-Datenpunkte nicht oder bleiben stehen?</a></p><p><a id="wled-shown-offline-after-restart"></a></p><h2 id="warum-wird-wled-nach-neustart-oder-update-als-offline-angezeigt-und-verbindet-sich-lange-nicht" tabindex="-1">Warum wird WLED nach Neustart oder Update als offline angezeigt und verbindet sich lange nicht? <a class="header-anchor" href="#warum-wird-wled-nach-neustart-oder-update-als-offline-angezeigt-und-verbindet-sich-lange-nicht" aria-label="Permalink to &quot;Warum wird WLED nach Neustart oder Update als offline angezeigt und verbindet sich lange nicht?&quot;">​</a></h2><p><strong>Kurz:</strong> Nach einem Neustart oder Update von WLED ist das Gerät für den Adapter zuerst ausgefallen. Er prüft es danach im Takt des Polling-Intervalls und macht nach jedem Fehlversuch eine längere Pause. Hat das Gerät länger gebraucht, als die Versuche reichen, prüft er es nur noch einmal pro Stunde. Schneller geht es mit einem Neustart der Instanz. In v0.9.2 verbinden sich außerdem Geräte, die erst nach dem Adapterstart dazukamen, nach einem Ausfall gar nicht neu.</p><h3 id="warum-es-dauert" tabindex="-1">Warum es dauert <a class="header-anchor" href="#warum-es-dauert" aria-label="Permalink to &quot;Warum es dauert&quot;">​</a></h3><ul><li><strong>Erkennen:</strong> Ist das Gerät per WebSocket verbunden, merkt der Adapter den Ausfall erst, wenn auf sein <code>ping</code> innerhalb eines Intervalls kein <code>pong</code> kommt. Mit den voreingestellten 30 Sekunden dauert das bis zu einer Minute. Dann setzt er <code>_info._online</code> auf <code>false</code> und schließt die Verbindung.</li><li><strong>Warten:</strong> Danach versucht er das Gerät per HTTP zu erreichen, zuerst nach 30 Sekunden, dann nach 60, 120, 240 und 480 Sekunden. Startet WLED nach einem Firmware-Update erst nach einigen Minuten wieder, fällt die Rückkehr in eine dieser längeren Pausen.</li><li><strong>Lange Pause:</strong> Nach 5 Fehlversuchen prüft der Adapter das Gerät nur noch einmal pro Stunde. Das trifft Geräte, die länger als etwa 7 Minuten aus waren.</li><li><strong>Neu verbinden:</strong> Antwortet das Gerät wieder, liest der Adapter es neu ein, öffnet den WebSocket und setzt <code>_info._online</code> auf <code>true</code>.</li></ul><p>Den genauen Ablauf mit Bild zeigt <a href="./../referenz/instanz-einstellungen#often-adapter-retry-offline-device">Wie oft versucht der Adapter ein Offline-Gerät erneut zu erreichen?</a></p><h3 id="nach-einem-neustart-des-adapters" tabindex="-1">Nach einem Neustart des Adapters <a class="header-anchor" href="#nach-einem-neustart-des-adapters" aria-label="Permalink to &quot;Nach einem Neustart des Adapters&quot;">​</a></h3><p>Beim Start setzt der Adapter <code>_info._online</code> aller Geräte auf <code>false</code>. Danach verbindet er sich nacheinander mit jedem bekannten Gerät und wartet dabei je Gerät bis zu 3 Sekunden auf eine Antwort. Erst wenn ein Gerät geantwortet hat, steht es wieder auf <code>true</code>. Sind viele Geräte aus, dauert der Start deshalb länger. Die Überwachung aller Geräte startet 10 Sekunden nach dem Start, im Log steht dann <code>WLED initialisation finalized, ready to do my job have fun !</code>.</p><h3 id="so-verbindet-sich-ein-gerat-schneller" tabindex="-1">So verbindet sich ein Gerät schneller <a class="header-anchor" href="#so-verbindet-sich-ein-gerat-schneller" aria-label="Permalink to &quot;So verbindet sich ein Gerät schneller&quot;">​</a></h3><ol><li><strong>Instanz neu starten.</strong> Der Adapter verbindet sich beim Start sofort mit allen bekannten Geräten.</li><li><strong>Intervall verkleinern.</strong> Ein kleineres „Intervall in Sekunden“ verkürzt alle Wartezeiten. Der Adapter prüft dann aber auch öfter.</li><li><strong>Backoff ausschalten oder mehr Versuche erlauben.</strong> Dann bleibt die Pause bei einem Intervall, und die Stunde Pause kommt später oder seltener.</li><li><strong>Stabiles Netz.</strong> Gib dem Gerät eine feste IP-Adresse und sorge für guten WLAN-Empfang. Wechselt die IP-Adresse, erreicht der Adapter das Gerät unter der gespeicherten Adresse nicht mehr.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Bis v0.9.2:</strong> Geräte, die erst nach dem Adapterstart dazukamen, über die laufende Bonjour-Suche, „Neue Geräte suchen“ oder per IP-Adresse, überwacht der Adapter nicht. Nach einem Neustart von WLED bleiben sie offline, bis du die Instanz neu startest.</p></div><p><strong>Ab v0.9.3:</strong> Auch diese Geräte werden überwacht und verbinden sich nach einem Ausfall von selbst neu (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/901" target="_blank" rel="noreferrer">#901</a>). Schließt WLED die WebSocket-Verbindung beim Neustart selbst, merkt der Adapter das sofort, setzt <code>_info._online</code> auf <code>false</code> und schreibt <code>&lt;Gerät&gt; disconnected</code> ins Log (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>).</p><p><strong>Ab v0.10.0:</strong> Schreibst du einen Befehl an ein Gerät, das als offline gilt, versucht der Adapter sofort, es neu zu verbinden. Ein Gerät, das wieder eingeschaltet ist, steuerst du damit gleich, statt auf die nächste Prüfung zu warten, die bis zu einer Stunde entfernt sein kann (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/939" target="_blank" rel="noreferrer">#939</a>).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Ältere Meldungen, nach denen der Adapter nach einem Neustart von WLED gar nicht mehr verbindet oder Geräte mit WLED 0.13 dauerhaft als offline zeigt, betreffen Versionen bis v0.6.5. Aktualisiere in diesem Fall den Adapter.</p></div><p><strong>Siehe auch:</strong> <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät wirklich online ist?</a> · <a href="./../anleitungen/geraete-verwalten#deal-switched-off-offline-devices">Wie gehe ich mit ausgeschalteten oder offline Geräten um?</a></p><p><a id="wled-devices-show-red-offline"></a></p><h2 id="warum-zeigen-alle-wled-rot-oder-offline-oder-der-esp-sturzt-ab" tabindex="-1">Warum zeigen alle WLED rot oder offline, oder der ESP stürzt ab? <a class="header-anchor" href="#warum-zeigen-alle-wled-rot-oder-offline-oder-der-esp-sturzt-ab" aria-label="Permalink to &quot;Warum zeigen alle WLED rot oder offline, oder der ESP stürzt ab?&quot;">​</a></h2><p><strong>Kurz:</strong> Sind alle Geräte gleichzeitig rot oder offline, liegt es meist an einer alten Adapterversion, am Netz des ioBroker-Hosts oder daran, dass zu viele Programme gleichzeitig per WebSocket mit WLED verbunden sind. Stürzt der ESP ab oder verliert er das WLAN, fehlt ihm meist Speicher. Aktualisiere zuerst den Adapter und schließ WLED-Oberflächen, die du nicht brauchst.</p><h3 id="ursachen-und-gegenmaßnahmen" tabindex="-1">Ursachen und Gegenmaßnahmen <a class="header-anchor" href="#ursachen-und-gegenmaßnahmen" aria-label="Permalink to &quot;Ursachen und Gegenmaßnahmen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ursache</th><th>Woran du es erkennst</th><th>Was du tust</th></tr></thead><tbody><tr><td>Zu viele WebSocket-Verbindungen zum Gerät. WLED hält auf einem ESP8266 höchstens 3, auf einem ESP32 höchstens 8 und trennt die ältesten. Jede offene WLED-Oberfläche im Browser, die WLED-App und andere Systeme belegen einen Platz.</td><td><code>wled.&lt;Instanz&gt;.&lt;MAC&gt;._info.ws</code> zeigt viele Verbindungen. Das Gerät geht immer wieder kurz offline und verbindet sich neu.</td><td>Schließ WLED-Oberflächen und Apps, die du nicht brauchst. Verbinde dasselbe Gerät nicht mit mehreren Systemen oder Adapter-Instanzen gleichzeitig.</td></tr><tr><td>Zu wenig freier Speicher auf dem ESP. WLED trennt dann alle WebSocket-Verbindungen, ein ESP8266 verliert unter Umständen das WLAN.</td><td><code>_info.freeheap</code> ist sehr klein. Das Gerät startet neu oder ist kurz nicht erreichbar.</td><td>Weniger Verbindungen, weniger LEDs oder Segmente je Gerät. Für große Installationen ist ein ESP32 die bessere Wahl, er hat mehr Speicher und mehr Plätze für Verbindungen.</td></tr><tr><td>Alte Adapterversion. Bis v0.5.x fragte der Adapter das Gerät ständig komplett per HTTP ab und belastete kleine ESPs stark.</td><td>Im Log steht zum Beispiel <code>Cannot read property &#39;error&#39; of undefined</code>.</td><td>Aktualisiere den Adapter. Seit v0.6.0 hält er eine WebSocket-Verbindung und sendet im Normalbetrieb nur ein <code>ping</code> im Takt des Polling-Intervalls.</td></tr><tr><td>Der ioBroker-Host hat kein Netz zu den Geräten.</td><td>Alle Geräte sind gleichzeitig offline, auch Geräte, die sicher laufen. Die WLED-Oberfläche öffnet sich vom ioBroker-Host aus nicht.</td><td>Prüf Netz, Firewall und VLANs zwischen ioBroker und WLED.</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Bis v0.9.3:</strong> Die Gerätetabelle in den Instanzeinstellungen liest den Status nur beim Öffnen. Steht dort alles auf rot, öffne die Einstellungen neu und vergleiche mit <code>_info._online</code> im Objektbaum.</p></div><p><strong>Ab v0.10.0:</strong> Die Geräteliste in den neu aufgebauten Instanzeinstellungen lädt den Status alle 10 Sekunden neu (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><p><strong>Siehe auch:</strong> <a href="./../referenz/log-meldungen#errors-about-unreachable-devices-websocket">Was bedeuten die Fehler &quot;Gerät nicht erreichbar&quot; und &quot;WebSocket was closed before the connection was established&quot;?</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät wirklich online ist?</a></p><p><a id="about-multiple-adapter-processes-already"></a></p><h2 id="was-tue-ich-bei-mehreren-adapter-prozessen-oder-already-running-und-onunload-fehlern" tabindex="-1">Was tue ich bei mehreren Adapter-Prozessen oder &quot;already running&quot; und onUnload-Fehlern? <a class="header-anchor" href="#was-tue-ich-bei-mehreren-adapter-prozessen-oder-already-running-und-onunload-fehlern" aria-label="Permalink to &quot;Was tue ich bei mehreren Adapter-Prozessen oder &quot;already running&quot; und onUnload-Fehlern?&quot;">​</a></h2><p><strong>Kurz:</strong> Mehrere Prozesse derselben Instanz, Geräte, die doppelt erscheinen, und Fehler beim Beenden wie <code>Cannot read property &#39;error&#39; of undefined at Wled.onUnload</code> stammen von Adapterversionen aus 2021 und sind seit v0.6.5 behoben. Siehst du so etwas heute, aktualisiere den Adapter. Laufen trotzdem mehrere Prozesse, beende die Instanz, beende übrig gebliebene Prozesse von Hand und starte die Instanz neu.</p><h3 id="woran-du-es-erkennst" tabindex="-1">Woran du es erkennst <a class="header-anchor" href="#woran-du-es-erkennst" aria-label="Permalink to &quot;Woran du es erkennst&quot;">​</a></h3><ul><li>Im Log steht beim Neustart der Instanz ein Fehler aus <code>onUnload</code>, zum Beispiel <code>TypeError: Cannot read property &#39;error&#39; of undefined at Wled.onUnload</code>.</li><li>Die Instanz meldet beim Start, dass sie schon läuft, oder Geräte stehen doppelt in der Liste.</li><li>Der Adapter reagiert nicht mehr, Datenpunkte ändern sich weder von WLED noch von ioBroker aus, und ein Neustart der Instanz hilft nicht.</li><li>Auf der Konsole des ioBroker-Hosts laufen mehrere Prozesse für dieselbe Instanz.</li></ul><h3 id="so-beendest-du-hangende-prozesse" tabindex="-1">So beendest du hängende Prozesse <a class="header-anchor" href="#so-beendest-du-hangende-prozesse" aria-label="Permalink to &quot;So beendest du hängende Prozesse&quot;">​</a></h3><ol><li>Stoppe die Instanz im Admin unter „Instanzen“ oder auf der Konsole mit <code>iobroker stop wled.0</code>.</li><li>Prüfe auf der Konsole, ob noch Prozesse der Instanz laufen. Unter Linux zeigt <code>ps aux | grep io.wled</code> alle Prozesse, deren Name mit <code>io.wled.</code> beginnt. Die Zeile mit <code>grep</code> selbst kannst du ignorieren.</li><li>Laufen noch Prozesse, beende sie mit <code>kill &lt;PID&gt;</code>. Die PID steht in der zweiten Spalte der Ausgabe.</li><li>Starte die Instanz wieder mit <code>iobroker start wled.0</code> oder im Admin.</li><li>Hilft das nicht, starte ioBroker als Ganzes neu: <code>iobroker restart</code>.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Unter Windows läuft ioBroker als Dienst. <code>iobroker stop</code> und <code>iobroker restart</code> funktionieren dort nicht wie unter Linux. Starte den Dienst stattdessen über die Windows-Dienste oder <code>serviceIoBroker.bat</code> neu.</p></div><h3 id="was-der-adapter-heute-beim-beenden-aufraumt" tabindex="-1">Was der Adapter heute beim Beenden aufräumt <a class="header-anchor" href="#was-der-adapter-heute-beim-beenden-aufraumt" aria-label="Permalink to &quot;Was der Adapter heute beim Beenden aufräumt&quot;">​</a></h3><p>Beim Beenden der Instanz setzt der Adapter <code>_info._online</code> aller Geräte auf <code>false</code>, stoppt für jedes Gerät die Timer, schließt die WebSocket-Verbindungen, beendet die Bonjour-Suche und setzt <code>info.connection</code> auf <code>false</code>. Im Log steht danach <code>cleaned everything up...</code>. Seit v0.9.0 räumt er Timer und WebSocket auch auf, wenn du ein einzelnes Gerät löschst.</p><p><strong>Bis v0.9.2:</strong> Der Timer der Überwachung kann verloren gehen, weil der Ping-Timer seine Kennung überschreibt. Beim Beenden lässt er sich dann nicht stoppen.</p><p><strong>Ab v0.9.3:</strong> Der Ping-Timer überschreibt die Kennung nicht mehr (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/902" target="_blank" rel="noreferrer">#902</a>). Alle Timer laufen über die Timer-Funktionen von ioBroker, die beim Beenden der Instanz alle offenen Timer stoppen.</p><p><strong>Siehe auch:</strong> <a href="#adapter-not-start-stop-responding">Warum startet der Adapter nach einem Update nicht oder reagiert nicht mehr?</a> · <a href="./../anleitungen/geraete-verwalten#remove-wled-device-adapter">Wie entferne ich ein WLED-Gerät aus dem Adapter?</a></p>',66)])])}const b=t(d,[["render",s]]);export{m as __pageData,b as default};
